/* ============================================================
   أطياب الجاسم (React) — قسم دهن العود ثلاثي الأبعاد (OudOil3D)

   الغلاف حول مشهد المالك (BukhoorScene) بنفس عقد المبخرة:
     · تحميل كسول: لا يُركَّب المشهد (≈2.4 م.ب + three.js) إلا إذا
       اقترب قسمه من الشاشة (IntersectionObserver بهامش 900px)، أو
       حدث تمرير في أي حاوية، أو تفاعل حقيقي من العميل، أو مهلة
       5 ثوانٍ بعد استقرار الصفحة (تُحترم «توفير البيانات» و2g/3g).
     · نقرة واحدة (بلا سحب) + Enter/Space تفتح صفحة العود — كما
       في قسمي العطور (R6) والبخور.
     · لودر ذهبي حتى إعلان المشهد جاهزيته، ومهلة 30 ثانية تُخفيه
       (تبقى صورة الخلفية كملصق) بلا شاشة فارغة أبدًا.
   ============================================================ */

import { useCallback, useEffect, useRef, useState, lazy, Suspense } from "react";
import { useNavigate } from "react-router-dom";
import { PATHS } from "../../routes.js";
/* ★ R22: فصل المشهد في حزمة مستقلة (code-split) — three.js الخاص به
   + النموذج (2.4 م.ب) لا يُنزَّلان إلا عند الاقتراب من القسم. */
const BukhoorScene = lazy(function () {
  return import("./BukhoorScene.jsx");
});

export default function OudOil3D() {
  const navigate = useNavigate();
  const rootRef = useRef(null);
  const pressRef = useRef(null);
  const armedRef = useRef(false);
  const watchdogRef = useRef(0);
  const [near, setNear] = useState(false);
  const [ready, setReady] = useState(false);
  /* ★ إصلاح الخلل: كان الفشل صامتاً — اللودر يدور إلى الأبد ثم يختفي
     فجأة (مهلة 30 ثانية تُخفيه كأن المشهد جاهز) بلا زر إعادة. الآن حالة
     فشل صريحة مع زر إعادة المحاولة مثل قسم البخور. */
  const [failed, setFailed] = useState(false);
  const [failDetail, setFailDetail] = useState("");
  const [sceneKey, setSceneKey] = useState(0);

  /* ---------- التحميل الكسول: اقتراب القسم أو تفاعل العميل ---------- */
  useEffect(function () {
    if (armedRef.current) return undefined;
    const el = rootRef.current;
    if (!el) return undefined;

    let armTimer = 0;
    let io = null;
    let checks = [];

    function isVisible() {
      if (el.closest("[hidden]")) return false;
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    }

    function isNear() {
      if (!isVisible()) return false;
      const r = el.getBoundingClientRect();
      const h = window.innerHeight || 800;
      return r.top < h + 900 && r.bottom > -700;
    }

    function cleanup() {
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("scrollend", onScroll, true);
      ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
        window.removeEventListener(ev, onInteract, true);
      });
      if (io) {
        io.disconnect();
        io = null;
      }
      checks.forEach(function (t) {
        window.clearTimeout(t);
      });
      checks = [];
    }

    function fire(delay) {
      if (armedRef.current) return;
      if (armTimer) window.clearTimeout(armTimer);
      armTimer = window.setTimeout(function () {
        if (armedRef.current) return;
        armedRef.current = true;
        setNear(true);
        cleanup();
      }, delay || 300);
    }

    function onInteract() {
      fire(600);
    }

    function onScroll() {
      if (isNear()) fire(300);
    }

    if (!("IntersectionObserver" in window)) {
      armTimer = window.setTimeout(function () {
        if (!armedRef.current) {
          armedRef.current = true;
          setNear(true);
        }
      }, 0);
      return function () {
        if (armTimer) window.clearTimeout(armTimer);
      };
    }

    io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) fire(300);
        });
      },
      { rootMargin: "900px 0px" }
    );
    io.observe(el);

    window.addEventListener("scroll", onScroll, { passive: true, capture: true });
    window.addEventListener("scrollend", onScroll, { passive: true, capture: true });
    ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
      window.addEventListener(ev, onInteract, { passive: true, capture: true });
    });

    if (isNear()) fire(350);

    checks = [600, 1500, 3000].map(function (ms) {
      return window.setTimeout(function () {
        if (isNear()) fire(200);
      }, ms);
    });

    const conn = (typeof navigator !== "undefined" && navigator.connection) || {};
    const frugal = !!conn.saveData || /^(slow-2g|2g|3g)$/.test(conn.effectiveType || "");
    if (!frugal) {
      checks.push(
        window.setTimeout(function () {
          fire(300);
        }, 5000)
      );
    }

    return function () {
      cleanup();
      if (armTimer) window.clearTimeout(armTimer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---------- مهلة الفشل (تبقى الخلفية كملصق + زر إعادة) ---------- */
  useEffect(
    function () {
      if (!near || ready || failed) return undefined;
      if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
      /* 60 ثانية: حزمة three.js + نموذج 2.4 م.ب من الخارج قد يتأخران على
         شبكة بطيئة؛ قبلها كان اللودر يختفي فجأة كأن المشهد جاهز. */
      watchdogRef.current = window.setTimeout(function () {
        setFailed(true);
        setFailDetail("انتهت مدة انتظار المشهد — أعد المحاولة");
      }, 60000);
      return function () {
        if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
        watchdogRef.current = 0;
      };
    },
    [near, ready, failed]
  );

  function onSceneReady() {
    if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
    watchdogRef.current = 0;
    setFailed(false);
    setReady(true);
  }

  function onSceneError(err) {
    if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
    watchdogRef.current = 0;
    setFailed(true);
    setFailDetail((err && err.message) || "تعذّر تحميل المشهد ثلاثي الأبعاد.");
  }

  const retry = useCallback(function () {
    setFailed(false);
    setFailDetail("");
    setReady(false);
    /* إعادة تركيب المشهد بمفتاح جديد (يُعيد تنزيل النموذج ومحاولة WebGL) */
    setSceneKey(function (k) {
      return k + 1;
    });
  }, []);

  /* ---------- نقرة واحدة (بلا سحب) تفتح صفحة العود ---------- */
  const resetPress = useCallback(function () {
    pressRef.current = null;
  }, []);

  const onPointerDown = useCallback(function (e) {
    pressRef.current = { x: e.clientX, y: e.clientY, t: Date.now(), target: e.target };
  }, []);

  const onPointerUp = useCallback(
    function (e) {
      const start = pressRef.current;
      pressRef.current = null;
      if (!start) return;
      if (Math.abs(e.clientX - start.x) > 8 || Math.abs(e.clientY - start.y) > 8) return;
      if (Date.now() - start.t > 700) return;
      if (start.target && start.target.closest && start.target.closest("button, a, input, select, label")) return;
      navigate(PATHS.ouds);
    },
    [navigate]
  );

  return (
    <div className="void-frame showcase-media">
      <span className="scene-tag">
        <i /> دهن العود ثلاثي الأبعاد · مشهد حيّ
      </span>
      <div className="oud-stage">
        <div
          className={"oud-root" + (ready ? " is-ready" : "")}
          id="oudRoot"
          ref={rootRef}
          role="link"
          tabIndex={0}
          title="انقر لعرض دهن العود"
          aria-label="مشهد دهن العود — انقر لعرض العود"
          onPointerDown={onPointerDown}
          onPointerUp={onPointerUp}
          onPointerCancel={resetPress}
          onKeyDown={function (e) {
            if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
              e.preventDefault();
              navigate(PATHS.ouds);
            }
          }}
        >
          {near ? (
            <Suspense fallback={null}>
              <BukhoorScene
                key={sceneKey}
                className="oud-canvas"
                style={{ position: "absolute", inset: 0 }}
                effects
                autoRotate={false}
                onReady={onSceneReady}
                onError={onSceneError}
              />
            </Suspense>
          ) : null}
          {ready || failed ? null : (
            <div className="mabkhara-loader">
              <span className="mabkhara-ring" />
              <span className="mabkhara-loader-text">جارٍ تحميل المشهد…</span>
            </div>
          )}
          {failed ? (
            <div className="mabkhara-error" id="oudError">
              <p>تعذّر تحميل المشهد ثلاثي الأبعاد.</p>
              <span className="mabkhara-error-detail">{failDetail}</span>
              <button className="mabkhara-retry" type="button" onClick={retry}>
                إعادة المحاولة
              </button>
            </div>
          ) : null}
          {/* ★ R22: حُذف «اسحب لتدوير المشهد» — المشهد لا يدور بالسحب
             (parallax خفيف على الديسكتوب فقط)، فالنص كان مضللًا. */}
          <div className="mabkhara-hint is-visible">
            انقر لعرض دهن العود
          </div>
        </div>
      </div>
    </div>
  );
}
